/* c-L6.js — C Lesson 6 content (EN + TR) */
var C_L6 = {
en: "<p class=\"l-text\">File I/O in C uses <code>FILE</code> pointers from <code>&lt;stdio.h&gt;</code>. The pattern is always the same: open a file, check if it succeeded, read/write, then close. This open-check-use-close pattern is fundamental to resource management in C — there is no garbage collector to clean up after you.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 WHAT YOU'LL LEARN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>Read and write files with fopen, fread, fwrite, fprintf, and fclose</li><li>Split a project across multiple .c and .h files with proper includes</li><li>Write a Makefile that compiles, links, and cleans incrementally</li><li>Use header guards and forward declarations to prevent multiple-definition errors</li><li>Build a small command-line tool that accepts arguments and processes a file</li></ul></div><div class=\"l-highlight\"><strong>File modes explained:</strong><br><code>\"r\"</code> — Read. File must exist. Pointer starts at beginning.<br><code>\"w\"</code> — Write. Creates file if missing. <strong>Destroys existing contents!</strong><br><code>\"a\"</code> — Append. Creates if missing. Pointer starts at end. Existing data preserved.<br><code>\"r+\"</code> — Read and write. File must exist.<br><code>\"w+\"</code> — Read and write. Creates/truncates.<br><code>\"rb\"</code>, <code>\"wb\"</code>, <code>\"ab\"</code> — Binary versions. Required on Windows for non-text files.</div><p class=\"l-text\"><strong>Text vs binary files:</strong> Text files contain human-readable characters (CSV, JSON, config files, logs). Binary files store raw bytes (images, audio, compiled programs, database files). Use text I/O (<code>fprintf</code>/<code>fgets</code>) for text files and binary I/O (<code>fread</code>/<code>fwrite</code>) for binary files.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> text_io.c — Write and read a text file <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* === WRITE === */</span>\n    <span class=\"ty\">FILE</span> *fw = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!fw) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"Cannot open students.txt for writing\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Name,Age,GPA\\n\"</span>);             <span class=\"cm\">/* header */</span>\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Begüm O,%d,%.2f\\n\"</span>, <span class=\"num\">30</span>, <span class=\"num\">3.85</span>);\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Mikail Sarpkaya,%d,%.2f\\n\"</span>, <span class=\"num\">32</span>, <span class=\"num\">3.50</span>);\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Defne Yıldız,%d,%.2f\\n\"</span>, <span class=\"num\">21</span>, <span class=\"num\">3.92</span>);\n    <span class=\"fn\">fclose</span>(fw);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Wrote students.txt\\n\\n\"</span>);\n\n    <span class=\"cm\">/* === READ === */</span>\n    <span class=\"ty\">FILE</span> *fr = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"kw\">if</span> (!fr) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"Cannot open students.txt for reading\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"ty\">char</span> line[<span class=\"num\">256</span>];\n    <span class=\"ty\">int</span> line_num = <span class=\"num\">0</span>;\n    <span class=\"kw\">while</span> (<span class=\"fn\">fgets</span>(line, <span class=\"kw\">sizeof</span>(line), fr)) {\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"Line %d: %s\"</span>, ++line_num, line);\n    }\n    <span class=\"fn\">fclose</span>(fr);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Wrote students.txt\n\nLine 1: Name,Age,GPA\nLine 2: Begüm O,30,3.85\nLine 3: Mikail Sarpkaya,32,3.50\nLine 4: Defne Yıldız,21,3.92</code></pre></div></div><div class=\"l-warn\"><strong>Warning:</strong> Always check <code>fopen</code> return value! If the file does not exist (for <code>\"r\"</code>) or cannot be created (permissions, disk full), <code>fopen</code> returns <code>NULL</code>. Calling <code>fprintf</code> on a <code>NULL</code> pointer is undefined behavior and typically crashes.</div><p class=\"l-text\">Now let\\u0027s do <strong>binary file I/O</strong> — saving and loading structs directly to disk. This is how games save state, databases store records, and applications persist structured data.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> binary_io.c — Save/load a student database <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string.h&gt;</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">32</span>];\n    <span class=\"ty\">int</span>   age;\n    <span class=\"ty\">float</span> gpa;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* Create student records */</span>\n    <span class=\"ty\">Student</span> db[] = {\n        {<span class=\"str\">\"Begüm\"</span>, <span class=\"num\">30</span>, <span class=\"num\">3.85f</span>},\n        {<span class=\"str\">\"Mikail\"</span>, <span class=\"num\">32</span>, <span class=\"num\">3.50f</span>},\n        {<span class=\"str\">\"Defne\"</span>, <span class=\"num\">21</span>, <span class=\"num\">3.92f</span>}\n    };\n    <span class=\"ty\">int</span> count = <span class=\"kw\">sizeof</span>(db) / <span class=\"kw\">sizeof</span>(db[<span class=\"num\">0</span>]);\n\n    <span class=\"cm\">/* === WRITE binary === */</span>\n    <span class=\"ty\">FILE</span> *fw = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.bin\"</span>, <span class=\"str\">\"wb\"</span>);\n    <span class=\"kw\">if</span> (!fw) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen write\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n    <span class=\"fn\">fwrite</span>(&amp;count, <span class=\"kw\">sizeof</span>(<span class=\"ty\">int</span>), <span class=\"num\">1</span>, fw);               <span class=\"cm\">/* write count first */</span>\n    <span class=\"fn\">fwrite</span>(db, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Student</span>), count, fw);           <span class=\"cm\">/* write all records */</span>\n    <span class=\"fn\">fclose</span>(fw);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Saved %d students to students.bin\\n\\n\"</span>, count);\n\n    <span class=\"cm\">/* === READ binary === */</span>\n    <span class=\"ty\">FILE</span> *fr = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.bin\"</span>, <span class=\"str\">\"rb\"</span>);\n    <span class=\"kw\">if</span> (!fr) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen read\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"ty\">int</span> n;\n    <span class=\"fn\">fread</span>(&amp;n, <span class=\"kw\">sizeof</span>(<span class=\"ty\">int</span>), <span class=\"num\">1</span>, fr);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Loading %d students:\\n\"</span>, n);\n\n    <span class=\"ty\">Student</span> loaded;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; n; i++) {\n        <span class=\"fn\">fread</span>(&amp;loaded, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Student</span>), <span class=\"num\">1</span>, fr);\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"  %s, age %d, GPA %.2f\\n\"</span>, loaded.name, loaded.age, loaded.gpa);\n    }\n    <span class=\"fn\">fclose</span>(fr);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Saved 3 students to students.bin\n\nLoading 3 students:\n  Begüm, age 30, GPA 3.85\n  Mikail, age 32, GPA 3.50\n  Defne, age 21, GPA 3.92</code></pre></div></div><div class=\"l-note\"><strong>Tip:</strong> Binary files are faster and more compact than text files, but they are not portable across different architectures (endianness, struct padding). For cross-platform data exchange, use text formats (JSON, CSV) or standardized binary formats (Protocol Buffers, MessagePack).</div><div class=\"l-highlight\"><strong>The C Preprocessor</strong> — The preprocessor runs BEFORE the compiler sees your code. It handles <code>#include</code>, <code>#define</code>, <code>#ifdef</code>, and other directives. Understanding it is essential because it is how C achieves code reuse (headers), configuration (conditional compilation), and optimization (macros).</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> preprocessor.c — #define, macros, conditional compilation <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"cm\">/* Constants */</span>\n<span class=\"pp\">#define MAX_STUDENTS 100</span>\n<span class=\"pp\">#define PI 3.14159265358979</span>\n\n<span class=\"cm\">/* Macro with arguments (use parentheses!) */</span>\n<span class=\"pp\">#define MAX(a, b) ((a) &gt; (b) ? (a) : (b))</span>\n<span class=\"pp\">#define SQUARE(x) ((x) * (x))</span>\n\n<span class=\"cm\">/* Conditional compilation */</span>\n<span class=\"pp\">#define DEBUG 1</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Max students: %d\\n\"</span>, <span class=\"pp\">MAX_STUDENTS</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"PI: %.10f\\n\"</span>, <span class=\"pp\">PI</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"MAX(7, 3): %d\\n\"</span>, <span class=\"fn\">MAX</span>(<span class=\"num\">7</span>, <span class=\"num\">3</span>));\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"SQUARE(5): %d\\n\"</span>, <span class=\"fn\">SQUARE</span>(<span class=\"num\">5</span>));\n\n<span class=\"pp\">#if DEBUG</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"\\n[DEBUG] Debug mode is ON\\n\"</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"[DEBUG] Compiled at %s %s\\n\"</span>, <span class=\"pp\">__DATE__</span>, <span class=\"pp\">__TIME__</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"[DEBUG] File: %s, Line: %d\\n\"</span>, <span class=\"pp\">__FILE__</span>, <span class=\"pp\">__LINE__</span>);\n<span class=\"pp\">#endif</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Max students: 100\nPI: 3.1415926536\nMAX(7, 3): 7\nSQUARE(5): 25\n\n[DEBUG] Debug mode is ON\n[DEBUG] Compiled at Mar 20 2026 14:30:00\n[DEBUG] File: preprocessor.c, Line: 20</code></pre></div></div><div class=\"l-warn\"><strong>Warning:</strong> Macro arguments are NOT evaluated before substitution — they are pasted literally. <code>SQUARE(x+1)</code> expands to <code>((x+1) * (x+1))</code> which is correct because of our parentheses. Without them, <code>x+1*x+1</code> would give the wrong result. Always wrap macro arguments and the entire expression in parentheses.</div><p class=\"l-text\"><strong>Include guards</strong> prevent a header file from being included multiple times (which would cause duplicate definition errors). Every header file you write should have them:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> student.h — Header with include guard <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#ifndef STUDENT_H</span>     <span class=\"cm\">/* if STUDENT_H is not defined... */</span>\n<span class=\"pp\">#define STUDENT_H</span>     <span class=\"cm\">/* ...define it (so next include skips this) */</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">64</span>];\n    <span class=\"ty\">int</span>   age;\n    <span class=\"ty\">float</span> gpa;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"cm\">/* Function prototypes */</span>\n<span class=\"ty\">void</span> <span class=\"fn\">print_student</span>(<span class=\"kw\">const</span> <span class=\"ty\">Student</span> *s);\n<span class=\"ty\">void</span> <span class=\"fn\">save_students</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span> *filename, <span class=\"kw\">const</span> <span class=\"ty\">Student</span> *arr, <span class=\"ty\">int</span> n);\n<span class=\"ty\">int</span>  <span class=\"fn\">load_students</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span> *filename, <span class=\"ty\">Student</span> *arr, <span class=\"ty\">int</span> max_n);\n\n<span class=\"pp\">#endif</span> <span class=\"cm\">/* STUDENT_H */</span></code></pre></div></div><p class=\"l-text\"><strong>Makefile basics</strong> — As your project grows beyond a single file, you need a build system. Make is the simplest and most universal. A Makefile defines rules: what to build, what it depends on, and how to build it.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>MAKEFILE</span> Makefile <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># Compiler and flags</span>\n<span class=\"pp\">CC</span> = gcc\n<span class=\"pp\">CFLAGS</span> = -Wall -Wextra -std=c11 -g\n\n<span class=\"cm\"># Target: dependencies</span>\n<span class=\"cm\">#     recipe (must be indented with TAB, not spaces!)</span>\n\n<span class=\"pp\">all</span>: student_db\n\n<span class=\"pp\">student_db</span>: main.o student.o\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -o student_db main.o student.o\n\n<span class=\"pp\">main.o</span>: main.c student.h\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -c main.c\n\n<span class=\"pp\">student.o</span>: student.c student.h\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -c student.c\n\n<span class=\"pp\">clean</span>:\n\trm -f *.o student_db\n\n<span class=\"pp\">.PHONY</span>: all clean</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>BASH</span> Using Make <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># Build the project</span>\nmake\n\n<span class=\"cm\"># Clean build artifacts</span>\nmake clean\n\n<span class=\"cm\"># Rebuild from scratch</span>\nmake clean &amp;&amp; make</code></pre></div></div><p class=\"l-text\">Key Makefile concepts:</p><ul class=\"l-list\"><li><strong>Target</strong> — what you want to build (<code>student_db</code>, <code>main.o</code>)</li><li><strong>Dependencies</strong> — files the target depends on. If any dependency is newer than the target, the recipe runs.</li><li><strong>Recipe</strong> — shell commands to build the target. MUST be indented with a real TAB character (not spaces).</li><li><strong><code>.PHONY</code></strong> — marks targets that are not files (like <code>clean</code>)</li><li>Make only recompiles what changed — much faster than recompiling everything</li></ul><div class=\"l-note\"><strong>Tip:</strong> As your project grows, consider using <code>cmake</code> instead of raw Makefiles. CMake generates Makefiles (or Visual Studio projects, Xcode projects, Ninja files) from a higher-level description, making your build portable across platforms.</div><div class=\"l-highlight\"><strong>Random-access file I/O</strong> — Files are not just streams; you can jump to any byte. <code>fseek</code> moves the read/write position, <code>ftell</code> reports the current position, and <code>rewind</code> resets to the beginning. This is how databases index records: store the byte offset of each record, then <code>fseek</code> directly to it.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> seek_demo.c — fseek, ftell, rewind <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"kw\">typedef struct</span> { <span class=\"ty\">int</span> id; <span class=\"ty\">char</span> name[<span class=\"num\">16</span>]; } <span class=\"ty\">Rec</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *f = <span class=\"fn\">fopen</span>(<span class=\"str\">\"recs.bin\"</span>, <span class=\"str\">\"wb+\"</span>);\n    <span class=\"ty\">Rec</span> recs[] = {{<span class=\"num\">1</span>,<span class=\"str\">\"alpha\"</span>},{<span class=\"num\">2</span>,<span class=\"str\">\"beta\"</span>},{<span class=\"num\">3</span>,<span class=\"str\">\"gamma\"</span>}};\n    <span class=\"fn\">fwrite</span>(recs, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">3</span>, f);\n\n    <span class=\"cm\">/* Where are we now? */</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"After write, ftell = %ld\\n\"</span>, <span class=\"fn\">ftell</span>(f));\n\n    <span class=\"cm\">/* Jump directly to record #2 (zero-based index 1) */</span>\n    <span class=\"fn\">fseek</span>(f, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>) * <span class=\"num\">1</span>, <span class=\"pp\">SEEK_SET</span>);\n    <span class=\"ty\">Rec</span> r;\n    <span class=\"fn\">fread</span>(&amp;r, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">1</span>, f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Record #2: id=%d name=%s\\n\"</span>, r.id, r.name);\n\n    <span class=\"cm\">/* SEEK_END with negative offset reads from end */</span>\n    <span class=\"fn\">fseek</span>(f, -(<span class=\"ty\">long</span>)<span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"pp\">SEEK_END</span>);\n    <span class=\"fn\">fread</span>(&amp;r, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">1</span>, f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Last record: id=%d name=%s\\n\"</span>, r.id, r.name);\n\n    <span class=\"cm\">/* rewind() == fseek(f, 0, SEEK_SET) + clear error flags */</span>\n    <span class=\"fn\">rewind</span>(f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"After rewind, ftell = %ld\\n\"</span>, <span class=\"fn\">ftell</span>(f));\n\n    <span class=\"fn\">fclose</span>(f);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>After write, ftell = 60\nRecord #2: id=2 name=beta\nLast record: id=3 name=gamma\nAfter rewind, ftell = 0</code></pre></div></div><p class=\"l-text\"><strong>The three whence values</strong> for <code>fseek(f, offset, whence)</code>: <code>SEEK_SET</code> (from start), <code>SEEK_CUR</code> (from current position), <code>SEEK_END</code> (from end). A common idiom for getting file size:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> file_size.c — get total bytes <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"fn\">fseek</span>(f, <span class=\"num\">0</span>, <span class=\"pp\">SEEK_END</span>);\n<span class=\"ty\">long</span> bytes = <span class=\"fn\">ftell</span>(f);\n<span class=\"fn\">rewind</span>(f);  <span class=\"cm\">/* go back to read from beginning */</span></code></pre></div></div><div class=\"l-highlight\"><strong>Buffering, flushing, and error detection</strong> — C's stdio library buffers writes in memory to reduce expensive system calls. Output may sit in the buffer for a long time before reaching disk. <code>fflush(f)</code> forces the buffer to disk. <code>feof(f)</code> tells you if the last read hit end-of-file, and <code>ferror(f)</code> reports I/O errors. Always check both — <code>fgets</code> returns <code>NULL</code> for both EOF and error.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> buffer_check.c — fflush, feof, ferror <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *log = <span class=\"fn\">fopen</span>(<span class=\"str\">\"events.log\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!log) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"startup at t=0\\n\"</span>);\n    <span class=\"fn\">fflush</span>(log);  <span class=\"cm\">/* force to disk — critical before a crash-prone op! */</span>\n\n    <span class=\"cm\">/* Read it back and detect EOF cleanly */</span>\n    <span class=\"ty\">FILE</span> *r = <span class=\"fn\">fopen</span>(<span class=\"str\">\"events.log\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"ty\">char</span> buf[<span class=\"num\">128</span>];\n    <span class=\"kw\">while</span> (<span class=\"fn\">fgets</span>(buf, <span class=\"kw\">sizeof</span>(buf), r)) {\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"line: %s\"</span>, buf);\n    }\n\n    <span class=\"kw\">if</span> (<span class=\"fn\">feof</span>(r))  <span class=\"fn\">printf</span>(<span class=\"str\">\"reached EOF cleanly\\n\"</span>);\n    <span class=\"kw\">if</span> (<span class=\"fn\">ferror</span>(r)) <span class=\"fn\">perror</span>(<span class=\"str\">\"read error\"</span>);\n\n    <span class=\"fn\">fclose</span>(log);\n    <span class=\"fn\">fclose</span>(r);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-warn\"><strong>Buffer pitfall:</strong> If your program crashes (segfault, power loss, kill -9) before <code>fclose</code> runs, buffered data is lost. For crash-critical logs, call <code>fflush</code> after every write, or set line-buffered mode with <code>setvbuf</code>.</div><p class=\"l-text\"><strong>Character-level I/O</strong> — Sometimes line-buffered reads are wrong (interactive prompts, parsing one character at a time). Use <code>getc</code>/<code>putc</code> for single bytes and <code>fputs</code> for writing a whole string without formatting overhead.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> char_io.c — getc, putc, fputs <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *src = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"ty\">FILE</span> *dst = <span class=\"fn\">fopen</span>(<span class=\"str\">\"copy.txt\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!src || !dst) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"cm\">/* Byte-by-byte copy — works for any file type */</span>\n    <span class=\"ty\">int</span> c;\n    <span class=\"ty\">long</span> bytes = <span class=\"num\">0</span>;\n    <span class=\"kw\">while</span> ((c = <span class=\"fn\">getc</span>(src)) != <span class=\"pp\">EOF</span>) {\n        <span class=\"fn\">putc</span>(c, dst);\n        bytes++;\n    }\n\n    <span class=\"cm\">/* fputs: faster than fprintf for plain strings — no parsing */</span>\n    <span class=\"fn\">fputs</span>(<span class=\"str\">\"--- end ---\\n\"</span>, dst);\n\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Copied %ld bytes\\n\"</span>, bytes);\n    <span class=\"fn\">fclose</span>(src);\n    <span class=\"fn\">fclose</span>(dst);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-note\"><strong>Tip:</strong> <code>getc</code> returns <code>int</code>, not <code>char</code>, because it needs to encode <code>EOF</code> (-1) as a value distinct from any valid byte (0-255). Storing the result in a <code>char</code> truncates and breaks EOF detection.</div><p class=\"l-text\"><strong>Controlling buffering with setvbuf</strong> — C offers three buffering modes. <code>_IOFBF</code> (full): writes go to memory until the buffer fills (default for files). <code>_IOLBF</code> (line): writes flush on newline (default for terminals). <code>_IONBF</code> (none): every write goes directly to the OS — slow but safe for crash logs.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> setvbuf_demo.c — buffering modes <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *log = <span class=\"fn\">fopen</span>(<span class=\"str\">\"crash.log\"</span>, <span class=\"str\">\"w\"</span>);\n\n    <span class=\"cm\">/* Line-buffered: flush on every '\\n' — good for live tail -f */</span>\n    <span class=\"fn\">setvbuf</span>(log, <span class=\"pp\">NULL</span>, <span class=\"pp\">_IOLBF</span>, <span class=\"num\">1024</span>);\n\n    <span class=\"cm\">/* Or unbuffered: every byte hits disk immediately */</span>\n    <span class=\"cm\">/* setvbuf(log, NULL, _IONBF, 0); */</span>\n\n    <span class=\"cm\">/* Or fully buffered with a 64 KB buffer */</span>\n    <span class=\"cm\">/* setvbuf(log, NULL, _IOFBF, 65536); */</span>\n\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"event 1\\n\"</span>);  <span class=\"cm\">/* flushed at \\n */</span>\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"event 2\\n\"</span>);  <span class=\"cm\">/* flushed at \\n */</span>\n\n    <span class=\"fn\">fclose</span>(log);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><p class=\"l-text\"><strong>Redirecting standard streams with freopen</strong> — <code>stdout</code>, <code>stderr</code>, and <code>stdin</code> are just <code>FILE*</code> pointers. <code>freopen</code> reopens them to point at a different file — useful for redirecting program output without touching the shell.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> freopen_demo.c — redirect stderr to a log file <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* Send all stderr output to errors.log */</span>\n    <span class=\"kw\">if</span> (!<span class=\"fn\">freopen</span>(<span class=\"str\">\"errors.log\"</span>, <span class=\"str\">\"a\"</span>, stderr)) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"freopen stderr\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"normal output goes to console\\n\"</span>);\n    <span class=\"fn\">fprintf</span>(stderr, <span class=\"str\">\"this line lands in errors.log\\n\"</span>);\n    <span class=\"fn\">perror</span>(<span class=\"str\">\"simulated error\"</span>);  <span class=\"cm\">/* perror writes to stderr */</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-highlight\"><strong>Preprocessor deep dive</strong> — Beyond <code>#define</code> and <code>#if</code>, the preprocessor has a rich set of directives for conditional compilation, header management, diagnostics, and token manipulation. Mastering them lets you write portable code that adapts to compiler, platform, and configuration.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> conditional.c — #ifdef / #ifndef / #else / #elif <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"pp\">#define PLATFORM_LINUX</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n<span class=\"pp\">#ifdef PLATFORM_LINUX</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for Linux\\n\"</span>);\n<span class=\"pp\">#elif defined(PLATFORM_WIN)</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for Windows\\n\"</span>);\n<span class=\"pp\">#elif defined(PLATFORM_MAC)</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for macOS\\n\"</span>);\n<span class=\"pp\">#else</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Unknown platform\\n\"</span>);\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifndef NDEBUG</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Debug build (NDEBUG not set)\\n\"</span>);\n<span class=\"pp\">#endif</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><p class=\"l-text\"><strong><code>#undef</code></strong> removes a macro definition. Useful when a header pollutes your namespace or when you need to temporarily override a macro and restore it later.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> undef_demo.c — removing and redefining <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"pp\">#define MAX 100</span>\n<span class=\"fn\">printf</span>(<span class=\"str\">\"MAX=%d\\n\"</span>, <span class=\"pp\">MAX</span>);  <span class=\"cm\">/* 100 */</span>\n\n<span class=\"pp\">#undef MAX</span>\n<span class=\"pp\">#define MAX 500</span>\n<span class=\"fn\">printf</span>(<span class=\"str\">\"MAX=%d\\n\"</span>, <span class=\"pp\">MAX</span>);  <span class=\"cm\">/* 500 — no redefinition warning */</span>\n\n<span class=\"cm\">/* Common pattern: undefine a polluting macro from windows.h */</span>\n<span class=\"pp\">#undef min</span>\n<span class=\"pp\">#undef max</span>  <span class=\"cm\">/* now use std::min / std::max in C++ */</span></code></pre></div></div><p class=\"l-text\"><strong><code>#pragma once</code></strong> is a compiler-supported alternative to include guards. One line at the top of a header file, no matching <code>#endif</code> needed. Supported by GCC, Clang, MSVC — but not strictly portable (no ISO C guarantee).</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> student2.h — #pragma once alternative <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#pragma once</span>   <span class=\"cm\">/* same effect as #ifndef/#define/#endif triple */</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">64</span>];\n    <span class=\"ty\">int</span>   age;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"ty\">void</span> <span class=\"fn\">print_student</span>(<span class=\"kw\">const</span> <span class=\"ty\">Student</span> *s);</code></pre></div></div><div class=\"l-note\"><strong>Which to use?</strong> Classic <code>#ifndef</code> guards are 100% portable; <code>#pragma once</code> is shorter, can be slightly faster (compiler skips the file by inode), and immune to macro-name clashes. Most modern projects use <code>#pragma once</code>; library headers that need maximum portability still use traditional guards.</div><p class=\"l-text\"><strong><code>#error</code></strong> stops compilation with a custom message; <code>#warning</code> emits a diagnostic without stopping. Use them to enforce build-time requirements:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> diagnostics.c — #error and #warning <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#if __STDC_VERSION__ &lt; 201112L</span>\n<span class=\"pp\">#error \"This code requires C11 or later. Use gcc -std=c11.\"</span>\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifdef DEPRECATED_API</span>\n<span class=\"pp\">#warning \"DEPRECATED_API will be removed in v2.0 — migrate to new_api()\"</span>\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifndef BUILD_VERSION</span>\n<span class=\"pp\">#error \"BUILD_VERSION must be defined via -DBUILD_VERSION=...\"</span>\n<span class=\"pp\">#endif</span></code></pre></div></div><p class=\"l-text\"><strong>Stringification (<code>#</code>) and token pasting (<code>##</code>)</strong> are two preprocessor operators used inside macro bodies. <code>#x</code> converts macro argument <code>x</code> into a string literal. <code>a##b</code> concatenates two tokens into one identifier.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> macro_ops.c — # and ## operators <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"cm\">/* Stringification: turn the argument into a \"string literal\" */</span>\n<span class=\"pp\">#define STR(x) #x</span>\n<span class=\"pp\">#define ASSERT_EQ(a, b) </span>\\\n    <span class=\"pp\">((a) == (b) ? printf(STR(a) \" == \" STR(b) \" OK\\n\") </span>\\\n                 <span class=\"pp\">: printf(STR(a) \" != \" STR(b) \" FAIL\\n\"))</span>\n\n<span class=\"cm\">/* Token paste: join two tokens to form a new identifier */</span>\n<span class=\"pp\">#define MAKE_VAR(prefix, n) prefix##n</span>\n<span class=\"pp\">#define GETTER(field) </span>\\\n    <span class=\"ty\">int</span> <span class=\"fn\">get_##field</span>(<span class=\"kw\">struct</span> <span class=\"ty\">Point</span> *p) { <span class=\"kw\">return</span> p-&gt;field; }\n\n<span class=\"kw\">struct</span> <span class=\"ty\">Point</span> { <span class=\"ty\">int</span> x, y; };\n<span class=\"fn\">GETTER</span>(x)   <span class=\"cm\">/* expands to: int get_x(struct Point *p) {...} */</span>\n<span class=\"fn\">GETTER</span>(y)   <span class=\"cm\">/* expands to: int get_y(struct Point *p) {...} */</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">int</span> <span class=\"fn\">MAKE_VAR</span>(count, <span class=\"num\">1</span>) = <span class=\"num\">42</span>;   <span class=\"cm\">/* int count1 = 42; */</span>\n    <span class=\"ty\">int</span> <span class=\"fn\">MAKE_VAR</span>(count, <span class=\"num\">2</span>) = <span class=\"num\">99</span>;   <span class=\"cm\">/* int count2 = 99; */</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"count1=%d count2=%d\\n\"</span>, count1, count2);\n\n    <span class=\"fn\">ASSERT_EQ</span>(<span class=\"num\">2</span>+<span class=\"num\">2</span>, <span class=\"num\">4</span>);   <span class=\"cm\">/* prints: 2+2 == 4 OK */</span>\n    <span class=\"fn\">ASSERT_EQ</span>(<span class=\"num\">2</span>+<span class=\"num\">2</span>, <span class=\"num\">5</span>);   <span class=\"cm\">/* prints: 2+2 != 5 FAIL */</span>\n\n    <span class=\"kw\">struct</span> <span class=\"ty\">Point</span> p = {<span class=\"num\">10</span>, <span class=\"num\">20</span>};\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"x=%d y=%d\\n\"</span>, <span class=\"fn\">get_x</span>(&amp;p), <span class=\"fn\">get_y</span>(&amp;p));\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>count1=42 count2=99\n2+2 == 4 OK\n2+2 != 5 FAIL\nx=10 y=20</code></pre></div></div><div class=\"l-note\"><strong>Why it matters:</strong> Stringification powers logging macros that print the source expression (<code>LOG(x)</code> showing both <code>\"x\"</code> and its value). Token pasting powers code generation — generic containers, type-specific functions, X-macro tables — all without a separate codegen step.</div><div class=\"l-highlight\"><strong><code>#include &quot;...&quot;</code> vs <code>#include &lt;...&gt;</code></strong> — Both forms read a file and inject its contents, but they search different directories.<br><br><strong>Quotes <code>\"header.h\"</code></strong>: search the current source file's directory first, then fall back to the system include path. Use this for <strong>your own project headers</strong>.<br><br><strong>Angle brackets <code>&lt;header.h&gt;</code></strong>: search only the system include path (<code>/usr/include</code>, paths given via <code>-I</code>, compiler-installed headers). Use this for <strong>standard library and third-party</strong> headers.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> include_paths.c — practical example <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\">/* System / library headers — angle brackets */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>      <span class=\"cm\">/* C standard library */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string.h&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;SDL2/SDL.h&gt;</span>   <span class=\"cm\">/* third-party in system path */</span>\n\n<span class=\"cm\">/* Your project's own headers — quotes */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"student.h\"</span>    <span class=\"cm\">/* same directory as this .c file */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"util/log.h\"</span>   <span class=\"cm\">/* subdirectory relative path */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"../shared.h\"</span>  <span class=\"cm\">/* parent directory */</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) { <span class=\"kw\">return</span> <span class=\"num\">0</span>; }</code></pre></div></div><div class=\"l-warn\"><strong>Common pitfall:</strong> Using <code>&lt;myheader.h&gt;</code> for your own project file works only if you happen to pass <code>-I.</code> to the compiler. It is fragile and misleading. <strong>Quotes for project, angles for libraries</strong> — this convention makes intent obvious to readers and tools.</div><p class=\"l-text\">The search path can be extended with the <code>-I</code> compiler flag:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>BASH</span> Adding include directories <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># Add ./include to the search path (for both \"...\" and &lt;...&gt;)</span>\ngcc -Iinclude -o app main.c\n\n<span class=\"cm\"># Multiple paths searched in order</span>\ngcc -Iinclude -I/opt/mylib/include -o app main.c\n\n<span class=\"cm\"># See exactly which paths the compiler searches</span>\ngcc -v -E -x c /dev/null   <span class=\"cm\"># prints #include search paths</span></code></pre></div></div><p class=\"l-text\"><strong>Congratulations!</strong> You now have a solid foundation in C. You understand compilation, types, pointers, memory management, functions, arrays, strings, structs, file I/O, and the preprocessor. These concepts are the building blocks of systems programming and will serve you well whether you move to C++, Rust, or embedded systems.</p>",
tr: "<p class=\"l-text\">C'de dosya G/Ç işlemleri <code>&lt;stdio.h&gt;</code>'tan <code>FILE</code> işaretçileri kullanır. Düzen her zaman aynıdır: bir dosya aç, başarılı olup olmadığını kontrol et, oku/yaz, sonra kapat. Bu aç-kontrol et-kullan-kapat düzeni C'de kaynak yönetiminin temelidir — arkanızdan temizlik yapacak bir çöp toplayıcı yoktur.</p><div class=\"lesson-outcomes\" style=\"background:rgba(200,169,110,0.06);border-left:3px solid #c8a96e;padding:1rem 1.2rem;margin:1.5rem 0;border-radius:0 8px 8px 0\"><div style=\"font-size:0.78rem;font-weight:700;letter-spacing:0.08em;color:#c8a96e;margin-bottom:0.6rem\">📍 BU DERSTE ÖĞRENECEKSİN</div><ul style=\"margin:0;padding-left:1.3rem;line-height:1.65;font-size:0.93rem;color:rgba(235,230,220,0.92)\"><li>fopen, fread, fwrite, fprintf ve fclose ile dosya oku ve yaz</li><li>Bir projeyi uygun include'larla birden fazla .c ve .h dosyasına böl</li><li>Artımlı derleyen, linkleyen ve temizleyen bir Makefile yaz</li><li>Çoklu-tanım hatalarını önlemek için header guard ve forward declaration kullan</li><li>Argüman kabul eden ve dosya işleyen küçük bir CLI aracı inşa et</li></ul></div><div class=\"l-highlight\"><strong>Dosya modları açıklaması:</strong><br><code>\"r\"</code> — Oku. Dosya mevcut olmalıdır. İşaretçi başlangıçtan başlar.<br><code>\"w\"</code> — Yaz. Yoksa oluşturur. <strong>Mevcut içeriği yok eder!</strong><br><code>\"a\"</code> — Ekle. Yoksa oluşturur. İşaretçi sondan başlar. Mevcut veri korunur.<br><code>\"r+\"</code> — Oku ve yaz. Dosya mevcut olmalıdır.<br><code>\"w+\"</code> — Oku ve yaz. Oluşturur/keser.<br><code>\"rb\"</code>, <code>\"wb\"</code>, <code>\"ab\"</code> — İkili sürümler. Windows'ta metin olmayan dosyalar için gereklidir.</div><p class=\"l-text\"><strong>Metin vs ikili dosyalar:</strong> Metin dosyaları insan tarafından okunabilir karakterler içerir (CSV, JSON, yapılandırma dosyaları, günlükler). İkili dosyalar ham baytlar saklar (görüntüler, ses, derlenmiş programlar, veritabanı dosyaları). Metin dosyaları için metin G/Ç (<code>fprintf</code>/<code>fgets</code>) ve ikili dosyalar için ikili G/Ç (<code>fread</code>/<code>fwrite</code>) kullanın.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> text_io.c — Metin dosyası yaz ve oku <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* === YAZ === */</span>\n    <span class=\"ty\">FILE</span> *fw = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!fw) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"Cannot open students.txt for writing\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Name,Age,GPA\\n\"</span>);             <span class=\"cm\">/* başlık */</span>\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Begüm O,%d,%.2f\\n\"</span>, <span class=\"num\">30</span>, <span class=\"num\">3.85</span>);\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Mikail Sarpkaya,%d,%.2f\\n\"</span>, <span class=\"num\">32</span>, <span class=\"num\">3.50</span>);\n    <span class=\"fn\">fprintf</span>(fw, <span class=\"str\">\"Defne Yıldız,%d,%.2f\\n\"</span>, <span class=\"num\">21</span>, <span class=\"num\">3.92</span>);\n    <span class=\"fn\">fclose</span>(fw);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Wrote students.txt\\n\\n\"</span>);\n\n    <span class=\"cm\">/* === OKU === */</span>\n    <span class=\"ty\">FILE</span> *fr = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"kw\">if</span> (!fr) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"Cannot open students.txt for reading\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"ty\">char</span> line[<span class=\"num\">256</span>];\n    <span class=\"ty\">int</span> line_num = <span class=\"num\">0</span>;\n    <span class=\"kw\">while</span> (<span class=\"fn\">fgets</span>(line, <span class=\"kw\">sizeof</span>(line), fr)) {\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"Line %d: %s\"</span>, ++line_num, line);\n    }\n    <span class=\"fn\">fclose</span>(fr);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Wrote students.txt\n\nLine 1: Name,Age,GPA\nLine 2: Begüm O,30,3.85\nLine 3: Mikail Sarpkaya,32,3.50\nLine 4: Defne Yıldız,21,3.92</code></pre></div></div><div class=\"l-warn\"><strong>Uyarı:</strong> <code>fopen</code> dönüş değerini her zaman kontrol edin! Dosya yoksa (<code>\"r\"</code> için) veya oluşturulamıyorsa (izinler, disk dolu), <code>fopen</code> <code>NULL</code> döndürür. <code>NULL</code> işaretçide <code>fprintf</code> çağırmak tanımsız davranıştır ve genellikle çökmeye neden olur.</div><p class=\"l-text\">Şimdi <strong>ikili dosya G/Ç</strong> yapalım — struct'ları doğrudan diske kaydetme ve yükleme. Oyunlar durumu böyle kaydeder, veritabanları kayıtları böyle saklar ve uygulamalar yapılandırılmış verileri böyle kalıcı hale getirir.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> binary_io.c — Öğrenci veritabanını kaydet/yükle <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string.h&gt;</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">32</span>];\n    <span class=\"ty\">int</span>   age;\n    <span class=\"ty\">float</span> gpa;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* Öğrenci kayıtları oluştur */</span>\n    <span class=\"ty\">Student</span> db[] = {\n        {<span class=\"str\">\"Begüm\"</span>, <span class=\"num\">30</span>, <span class=\"num\">3.85f</span>},\n        {<span class=\"str\">\"Mikail\"</span>, <span class=\"num\">32</span>, <span class=\"num\">3.50f</span>},\n        {<span class=\"str\">\"Defne\"</span>, <span class=\"num\">21</span>, <span class=\"num\">3.92f</span>}\n    };\n    <span class=\"ty\">int</span> count = <span class=\"kw\">sizeof</span>(db) / <span class=\"kw\">sizeof</span>(db[<span class=\"num\">0</span>]);\n\n    <span class=\"cm\">/* === İkili YAZ === */</span>\n    <span class=\"ty\">FILE</span> *fw = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.bin\"</span>, <span class=\"str\">\"wb\"</span>);\n    <span class=\"kw\">if</span> (!fw) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen write\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n    <span class=\"fn\">fwrite</span>(&amp;count, <span class=\"kw\">sizeof</span>(<span class=\"ty\">int</span>), <span class=\"num\">1</span>, fw);               <span class=\"cm\">/* önce sayıyı yaz */</span>\n    <span class=\"fn\">fwrite</span>(db, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Student</span>), count, fw);           <span class=\"cm\">/* tüm kayıtları yaz */</span>\n    <span class=\"fn\">fclose</span>(fw);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Saved %d students to students.bin\\n\\n\"</span>, count);\n\n    <span class=\"cm\">/* === İkili OKU === */</span>\n    <span class=\"ty\">FILE</span> *fr = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.bin\"</span>, <span class=\"str\">\"rb\"</span>);\n    <span class=\"kw\">if</span> (!fr) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen read\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"ty\">int</span> n;\n    <span class=\"fn\">fread</span>(&amp;n, <span class=\"kw\">sizeof</span>(<span class=\"ty\">int</span>), <span class=\"num\">1</span>, fr);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Loading %d students:\\n\"</span>, n);\n\n    <span class=\"ty\">Student</span> loaded;\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = <span class=\"num\">0</span>; i &lt; n; i++) {\n        <span class=\"fn\">fread</span>(&amp;loaded, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Student</span>), <span class=\"num\">1</span>, fr);\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"  %s, age %d, GPA %.2f\\n\"</span>, loaded.name, loaded.age, loaded.gpa);\n    }\n    <span class=\"fn\">fclose</span>(fr);\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Saved 3 students to students.bin\n\nLoading 3 students:\n  Begüm, age 30, GPA 3.85\n  Mikail, age 32, GPA 3.50\n  Defne, age 21, GPA 3.92</code></pre></div></div><div class=\"l-note\"><strong>İpucu:</strong> İkili dosyalar metin dosyalarından daha hızlı ve daha kompakttır, ancak farklı mimariler arasında (endianness, struct doldurma) taşınabilir değildir. Platformlar arası veri alışverişi için metin formatları (JSON, CSV) veya standartlaştırılmış ikili formatlar (Protocol Buffers, MessagePack) kullanın.</div><div class=\"l-highlight\"><strong>C Önişlemcisi</strong> — Önişlemci, derleyici kodunuzu görmeden ÖNCE çalışır. <code>#include</code>, <code>#define</code>, <code>#ifdef</code> ve diğer yönergeleri işler. Onu anlamak çok önemlidir çünkü C'nin kod yeniden kullanımına (başlıklar), yapılandırmaya (koşullu derleme) ve optimizasyona (makrolar) ulaşma yoludur.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> preprocessor.c — #define, makrolar, koşullu derleme <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"cm\">/* Sabitler */</span>\n<span class=\"pp\">#define MAX_STUDENTS 100</span>\n<span class=\"pp\">#define PI 3.14159265358979</span>\n\n<span class=\"cm\">/* Argümanlı makro (parantez kullanın!) */</span>\n<span class=\"pp\">#define MAX(a, b) ((a) &gt; (b) ? (a) : (b))</span>\n<span class=\"pp\">#define SQUARE(x) ((x) * (x))</span>\n\n<span class=\"cm\">/* Koşullu derleme */</span>\n<span class=\"pp\">#define DEBUG 1</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Max students: %d\\n\"</span>, <span class=\"pp\">MAX_STUDENTS</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"PI: %.10f\\n\"</span>, <span class=\"pp\">PI</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"MAX(7, 3): %d\\n\"</span>, <span class=\"fn\">MAX</span>(<span class=\"num\">7</span>, <span class=\"num\">3</span>));\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"SQUARE(5): %d\\n\"</span>, <span class=\"fn\">SQUARE</span>(<span class=\"num\">5</span>));\n\n<span class=\"pp\">#if DEBUG</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"\\n[DEBUG] Debug mode is ON\\n\"</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"[DEBUG] Compiled at %s %s\\n\"</span>, <span class=\"pp\">__DATE__</span>, <span class=\"pp\">__TIME__</span>);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"[DEBUG] File: %s, Line: %d\\n\"</span>, <span class=\"pp\">__FILE__</span>, <span class=\"pp\">__LINE__</span>);\n<span class=\"pp\">#endif</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>Max students: 100\nPI: 3.1415926536\nMAX(7, 3): 7\nSQUARE(5): 25\n\n[DEBUG] Debug mode is ON\n[DEBUG] Compiled at Mar 20 2026 14:30:00\n[DEBUG] File: preprocessor.c, Line: 20</code></pre></div></div><div class=\"l-warn\"><strong>Uyarı:</strong> Makro argümanları ikameden önce değerlendirilmez — tam anlamıyla yapıştırılır. <code>SQUARE(x+1)</code> parantezlerimiz sayesinde doğru olarak <code>((x+1) * (x+1))</code>'e genişler. Onlar olmadan <code>x+1*x+1</code> yanlış sonuç verirdi. Makro argümanlarını ve tüm ifadeyi her zaman parantez içine alın.</div><p class=\"l-text\"><strong>Include korumaları</strong> bir başlık dosyasının birden fazla kez dahil edilmesini önler (bu, yinelenen tanım hatalarına neden olur). Yazdığınız her başlık dosyasında bunlar olmalıdır:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> student.h — Include korumalı başlık <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#ifndef STUDENT_H</span>     <span class=\"cm\">/* STUDENT_H tanımlı değilse... */</span>\n<span class=\"pp\">#define STUDENT_H</span>     <span class=\"cm\">/* ...tanımla (sonraki include bunu atlar) */</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">64</span>];\n    <span class=\"ty\">int</span>   age;\n    <span class=\"ty\">float</span> gpa;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"cm\">/* Fonksiyon prototipleri */</span>\n<span class=\"ty\">void</span> <span class=\"fn\">print_student</span>(<span class=\"kw\">const</span> <span class=\"ty\">Student</span> *s);\n<span class=\"ty\">void</span> <span class=\"fn\">save_students</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span> *filename, <span class=\"kw\">const</span> <span class=\"ty\">Student</span> *arr, <span class=\"ty\">int</span> n);\n<span class=\"ty\">int</span>  <span class=\"fn\">load_students</span>(<span class=\"kw\">const</span> <span class=\"ty\">char</span> *filename, <span class=\"ty\">Student</span> *arr, <span class=\"ty\">int</span> max_n);\n\n<span class=\"pp\">#endif</span> <span class=\"cm\">/* STUDENT_H */</span></code></pre></div></div><p class=\"l-text\"><strong>Makefile temelleri</strong> — Projeniz tek bir dosyanın ötesine büyüdükçe, bir derleme sistemine ihtiyacınız olur. Make en basit ve en evrensel olandır. Bir Makefile kurallar tanımlar: neyin derlenmesi gerektiği, neye bağımlı olduğu ve nasıl derlenmesi gerektiği.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>MAKEFILE</span> Makefile <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># Derleyici ve bayraklar</span>\n<span class=\"pp\">CC</span> = gcc\n<span class=\"pp\">CFLAGS</span> = -Wall -Wextra -std=c11 -g\n\n<span class=\"cm\"># Hedef: bağımlılıklar</span>\n<span class=\"cm\">#     tarif (TAB ile girintilenmeli, boşluk değil!)</span>\n\n<span class=\"pp\">all</span>: student_db\n\n<span class=\"pp\">student_db</span>: main.o student.o\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -o student_db main.o student.o\n\n<span class=\"pp\">main.o</span>: main.c student.h\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -c main.c\n\n<span class=\"pp\">student.o</span>: student.c student.h\n\t$(<span class=\"pp\">CC</span>) $(<span class=\"pp\">CFLAGS</span>) -c student.c\n\n<span class=\"pp\">clean</span>:\n\trm -f *.o student_db\n\n<span class=\"pp\">.PHONY</span>: all clean</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>BASH</span> Make kullanımı <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># Projeyi derle</span>\nmake\n\n<span class=\"cm\"># Derleme çıktılarını temizle</span>\nmake clean\n\n<span class=\"cm\"># Sıfırdan yeniden derle</span>\nmake clean &amp;&amp; make</code></pre></div></div><p class=\"l-text\">Temel Makefile kavramları:</p><ul class=\"l-list\"><li><strong>Hedef</strong> — derlemek istediğiniz şey (<code>student_db</code>, <code>main.o</code>)</li><li><strong>Bağımlılıklar</strong> — hedefin bağımlı olduğu dosyalar. Herhangi bir bağımlılık hedeften yeniyse, tarif çalışır.</li><li><strong>Tarif</strong> — hedefi derlemek için kabuk komutları. Gerçek bir TAB karakteriyle girintilenmeli (boşluk değil).</li><li><strong><code>.PHONY</code></strong> — dosya olmayan hedefleri işaretler (<code>clean</code> gibi)</li><li>Make sadece değişen şeyleri yeniden derler — her şeyi yeniden derlemekten çok daha hızlıdır</li></ul><div class=\"l-note\"><strong>İpucu:</strong> Projeniz büyüdükçe ham Makefile yerine <code>cmake</code> kullanmayı düşünün. CMake, daha üst düzey bir tanımdan Makefile'lar (veya Visual Studio projeleri, Xcode projeleri, Ninja dosyaları) üretir ve derlemenizi platformlar arası taşınabilir hale getirir.</div><div class=\"l-highlight\"><strong>Rastgele erişimli dosya G/Ç</strong> — Dosyalar sadece akış değildir; herhangi bir bayta atlayabilirsiniz. <code>fseek</code> okuma/yazma konumunu hareket ettirir, <code>ftell</code> mevcut konumu bildirir ve <code>rewind</code> başa döner. Veritabanları kayıtları böyle indeksler: her kaydın bayt ofsetini sakla, sonra doğrudan <code>fseek</code> ile oraya git.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> seek_demo.c — fseek, ftell, rewind <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"kw\">typedef struct</span> { <span class=\"ty\">int</span> id; <span class=\"ty\">char</span> name[<span class=\"num\">16</span>]; } <span class=\"ty\">Rec</span>;\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *f = <span class=\"fn\">fopen</span>(<span class=\"str\">\"recs.bin\"</span>, <span class=\"str\">\"wb+\"</span>);\n    <span class=\"ty\">Rec</span> recs[] = {{<span class=\"num\">1</span>,<span class=\"str\">\"alpha\"</span>},{<span class=\"num\">2</span>,<span class=\"str\">\"beta\"</span>},{<span class=\"num\">3</span>,<span class=\"str\">\"gamma\"</span>}};\n    <span class=\"fn\">fwrite</span>(recs, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">3</span>, f);\n\n    <span class=\"cm\">/* Şu an neredeyiz? */</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"After write, ftell = %ld\\n\"</span>, <span class=\"fn\">ftell</span>(f));\n\n    <span class=\"cm\">/* Doğrudan 2. kayda atla (sıfır-temelli indeks 1) */</span>\n    <span class=\"fn\">fseek</span>(f, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>) * <span class=\"num\">1</span>, <span class=\"pp\">SEEK_SET</span>);\n    <span class=\"ty\">Rec</span> r;\n    <span class=\"fn\">fread</span>(&amp;r, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">1</span>, f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Record #2: id=%d name=%s\\n\"</span>, r.id, r.name);\n\n    <span class=\"cm\">/* SEEK_END negatif ofsetle sondan okur */</span>\n    <span class=\"fn\">fseek</span>(f, -(<span class=\"ty\">long</span>)<span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"pp\">SEEK_END</span>);\n    <span class=\"fn\">fread</span>(&amp;r, <span class=\"kw\">sizeof</span>(<span class=\"ty\">Rec</span>), <span class=\"num\">1</span>, f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Last record: id=%d name=%s\\n\"</span>, r.id, r.name);\n\n    <span class=\"cm\">/* rewind() == fseek(f, 0, SEEK_SET) + hata bayraklarını temizle */</span>\n    <span class=\"fn\">rewind</span>(f);\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"After rewind, ftell = %ld\\n\"</span>, <span class=\"fn\">ftell</span>(f));\n\n    <span class=\"fn\">fclose</span>(f);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>After write, ftell = 60\nRecord #2: id=2 name=beta\nLast record: id=3 name=gamma\nAfter rewind, ftell = 0</code></pre></div></div><p class=\"l-text\"><strong>Üç whence değeri</strong> <code>fseek(f, offset, whence)</code> için: <code>SEEK_SET</code> (baştan), <code>SEEK_CUR</code> (mevcut konumdan), <code>SEEK_END</code> (sondan). Dosya boyutunu almak için yaygın bir kalıp:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> file_size.c — toplam bayt sayısı <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"fn\">fseek</span>(f, <span class=\"num\">0</span>, <span class=\"pp\">SEEK_END</span>);\n<span class=\"ty\">long</span> bytes = <span class=\"fn\">ftell</span>(f);\n<span class=\"fn\">rewind</span>(f);  <span class=\"cm\">/* baştan okumak için geri dön */</span></code></pre></div></div><div class=\"l-highlight\"><strong>Tamponlama, flush ve hata tespiti</strong> — C'nin stdio kütüphanesi pahalı sistem çağrılarını azaltmak için yazımları bellekte tamponlar. Çıktı, diske ulaşmadan önce tamponda uzun süre bekleyebilir. <code>fflush(f)</code> tamponu diske yazmaya zorlar. <code>feof(f)</code> son okumanın dosya sonuna ulaşıp ulaşmadığını söyler ve <code>ferror(f)</code> G/Ç hatalarını bildirir. Her ikisini de mutlaka kontrol edin — <code>fgets</code> hem EOF hem de hata için <code>NULL</code> döndürür.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> buffer_check.c — fflush, feof, ferror <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *log = <span class=\"fn\">fopen</span>(<span class=\"str\">\"events.log\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!log) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"startup at t=0\\n\"</span>);\n    <span class=\"fn\">fflush</span>(log);  <span class=\"cm\">/* diske zorla — çökme riski olan bir işlemden önce kritik! */</span>\n\n    <span class=\"cm\">/* Geri oku ve EOF'u temiz şekilde tespit et */</span>\n    <span class=\"ty\">FILE</span> *r = <span class=\"fn\">fopen</span>(<span class=\"str\">\"events.log\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"ty\">char</span> buf[<span class=\"num\">128</span>];\n    <span class=\"kw\">while</span> (<span class=\"fn\">fgets</span>(buf, <span class=\"kw\">sizeof</span>(buf), r)) {\n        <span class=\"fn\">printf</span>(<span class=\"str\">\"line: %s\"</span>, buf);\n    }\n\n    <span class=\"kw\">if</span> (<span class=\"fn\">feof</span>(r))  <span class=\"fn\">printf</span>(<span class=\"str\">\"reached EOF cleanly\\n\"</span>);\n    <span class=\"kw\">if</span> (<span class=\"fn\">ferror</span>(r)) <span class=\"fn\">perror</span>(<span class=\"str\">\"read error\"</span>);\n\n    <span class=\"fn\">fclose</span>(log);\n    <span class=\"fn\">fclose</span>(r);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-warn\"><strong>Tampon tuzağı:</strong> Programınız <code>fclose</code> çalışmadan önce çökerse (segfault, elektrik kesintisi, kill -9), tamponlanmış veri kaybolur. Çökmeye karşı kritik günlükler için her yazımdan sonra <code>fflush</code> çağırın veya <code>setvbuf</code> ile satır-tamponlu mod ayarlayın.</div><p class=\"l-text\"><strong>Karakter-düzeyi G/Ç</strong> — Bazen satır-tamponlu okumalar yanlıştır (etkileşimli istemler, tek karakter ayrıştırma). Tek baytlar için <code>getc</code>/<code>putc</code> ve formatlama yükü olmadan tüm bir dizgi yazmak için <code>fputs</code> kullanın.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> char_io.c — getc, putc, fputs <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *src = <span class=\"fn\">fopen</span>(<span class=\"str\">\"students.txt\"</span>, <span class=\"str\">\"r\"</span>);\n    <span class=\"ty\">FILE</span> *dst = <span class=\"fn\">fopen</span>(<span class=\"str\">\"copy.txt\"</span>, <span class=\"str\">\"w\"</span>);\n    <span class=\"kw\">if</span> (!src || !dst) { <span class=\"fn\">perror</span>(<span class=\"str\">\"fopen\"</span>); <span class=\"kw\">return</span> <span class=\"num\">1</span>; }\n\n    <span class=\"cm\">/* Bayt-bayt kopyalama — her dosya türü için çalışır */</span>\n    <span class=\"ty\">int</span> c;\n    <span class=\"ty\">long</span> bytes = <span class=\"num\">0</span>;\n    <span class=\"kw\">while</span> ((c = <span class=\"fn\">getc</span>(src)) != <span class=\"pp\">EOF</span>) {\n        <span class=\"fn\">putc</span>(c, dst);\n        bytes++;\n    }\n\n    <span class=\"cm\">/* fputs: düz dizgiler için fprintf'ten hızlı — ayrıştırma yok */</span>\n    <span class=\"fn\">fputs</span>(<span class=\"str\">\"--- end ---\\n\"</span>, dst);\n\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Copied %ld bytes\\n\"</span>, bytes);\n    <span class=\"fn\">fclose</span>(src);\n    <span class=\"fn\">fclose</span>(dst);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-note\"><strong>İpucu:</strong> <code>getc</code>, <code>char</code> değil <code>int</code> döndürür çünkü <code>EOF</code>'u (-1) geçerli herhangi bir bayttan (0-255) ayrı bir değer olarak kodlaması gerekir. Sonucu <code>char</code>'a koymak değeri keser ve EOF tespitini bozar.</div><p class=\"l-text\"><strong>setvbuf ile tamponlamayı kontrol</strong> — C üç tamponlama modu sunar. <code>_IOFBF</code> (tam): yazımlar tampon dolana kadar belleğe gider (dosyalar için varsayılan). <code>_IOLBF</code> (satır): yazımlar yeni satırda flush'lanır (terminaller için varsayılan). <code>_IONBF</code> (yok): her yazım doğrudan OS'a gider — yavaş ama çökme günlükleri için güvenli.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> setvbuf_demo.c — tamponlama modları <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">FILE</span> *log = <span class=\"fn\">fopen</span>(<span class=\"str\">\"crash.log\"</span>, <span class=\"str\">\"w\"</span>);\n\n    <span class=\"cm\">/* Satır-tamponlu: her '\\n' karakterinde flush — canlı tail -f için iyi */</span>\n    <span class=\"fn\">setvbuf</span>(log, <span class=\"pp\">NULL</span>, <span class=\"pp\">_IOLBF</span>, <span class=\"num\">1024</span>);\n\n    <span class=\"cm\">/* Ya da tamponsuz: her bayt anında diske gider */</span>\n    <span class=\"cm\">/* setvbuf(log, NULL, _IONBF, 0); */</span>\n\n    <span class=\"cm\">/* Ya da 64 KB tamponla tamamen tamponlu */</span>\n    <span class=\"cm\">/* setvbuf(log, NULL, _IOFBF, 65536); */</span>\n\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"event 1\\n\"</span>);  <span class=\"cm\">/* \\n karakterinde flush'landı */</span>\n    <span class=\"fn\">fprintf</span>(log, <span class=\"str\">\"event 2\\n\"</span>);  <span class=\"cm\">/* \\n karakterinde flush'landı */</span>\n\n    <span class=\"fn\">fclose</span>(log);\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><p class=\"l-text\"><strong>freopen ile standart akışları yönlendirme</strong> — <code>stdout</code>, <code>stderr</code> ve <code>stdin</code> sadece <code>FILE*</code> işaretçileridir. <code>freopen</code>, onları farklı bir dosyaya işaret edecek şekilde yeniden açar — kabuğa dokunmadan program çıktısını yönlendirmek için kullanışlıdır.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> freopen_demo.c — stderr'i bir günlük dosyasına yönlendir <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"cm\">/* Tüm stderr çıktısını errors.log dosyasına gönder */</span>\n    <span class=\"kw\">if</span> (!<span class=\"fn\">freopen</span>(<span class=\"str\">\"errors.log\"</span>, <span class=\"str\">\"a\"</span>, stderr)) {\n        <span class=\"fn\">perror</span>(<span class=\"str\">\"freopen stderr\"</span>);\n        <span class=\"kw\">return</span> <span class=\"num\">1</span>;\n    }\n\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"normal output goes to console\\n\"</span>);\n    <span class=\"fn\">fprintf</span>(stderr, <span class=\"str\">\"this line lands in errors.log\\n\"</span>);\n    <span class=\"fn\">perror</span>(<span class=\"str\">\"simulated error\"</span>);  <span class=\"cm\">/* perror stderr'e yazar */</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"l-highlight\"><strong>Önişlemci derinlemesine</strong> — <code>#define</code> ve <code>#if</code>'in ötesinde önişlemci; koşullu derleme, başlık yönetimi, tanılama ve token manipülasyonu için zengin bir yönerge setine sahiptir. Bunlara hakim olmak, derleyiciye, platforma ve yapılandırmaya uyum sağlayan taşınabilir kod yazmanızı sağlar.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> conditional.c — #ifdef / #ifndef / #else / #elif <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"pp\">#define PLATFORM_LINUX</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n<span class=\"pp\">#ifdef PLATFORM_LINUX</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for Linux\\n\"</span>);\n<span class=\"pp\">#elif defined(PLATFORM_WIN)</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for Windows\\n\"</span>);\n<span class=\"pp\">#elif defined(PLATFORM_MAC)</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Compiled for macOS\\n\"</span>);\n<span class=\"pp\">#else</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Unknown platform\\n\"</span>);\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifndef NDEBUG</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"Debug build (NDEBUG not set)\\n\"</span>);\n<span class=\"pp\">#endif</span>\n\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><p class=\"l-text\"><strong><code>#undef</code></strong> bir makro tanımını kaldırır. Bir başlık ad alanınızı kirlettiğinde veya bir makroyu geçici olarak geçersiz kılıp sonra geri yüklemeniz gerektiğinde kullanışlıdır.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> undef_demo.c — kaldırma ve yeniden tanımlama <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"pp\">#define MAX 100</span>\n<span class=\"fn\">printf</span>(<span class=\"str\">\"MAX=%d\\n\"</span>, <span class=\"pp\">MAX</span>);  <span class=\"cm\">/* 100 */</span>\n\n<span class=\"pp\">#undef MAX</span>\n<span class=\"pp\">#define MAX 500</span>\n<span class=\"fn\">printf</span>(<span class=\"str\">\"MAX=%d\\n\"</span>, <span class=\"pp\">MAX</span>);  <span class=\"cm\">/* 500 — yeniden tanım uyarısı yok */</span>\n\n<span class=\"cm\">/* Yaygın kalıp: windows.h'tan gelen kirletici makroyu kaldır */</span>\n<span class=\"pp\">#undef min</span>\n<span class=\"pp\">#undef max</span>  <span class=\"cm\">/* artık C++'ta std::min / std::max kullanılabilir */</span></code></pre></div></div><p class=\"l-text\"><strong><code>#pragma once</code></strong> include korumalarına derleyici-destekli bir alternatiftir. Bir başlık dosyasının tepesine tek satır, eşleşen <code>#endif</code> gerekmez. GCC, Clang, MSVC tarafından desteklenir — ancak kesinlikle taşınabilir değildir (ISO C garantisi yok).</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> student2.h — #pragma once alternatifi <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#pragma once</span>   <span class=\"cm\">/* #ifndef/#define/#endif üçlüsüyle aynı etki */</span>\n\n<span class=\"kw\">typedef struct</span> {\n    <span class=\"ty\">char</span>  name[<span class=\"num\">64</span>];\n    <span class=\"ty\">int</span>   age;\n} <span class=\"ty\">Student</span>;\n\n<span class=\"ty\">void</span> <span class=\"fn\">print_student</span>(<span class=\"kw\">const</span> <span class=\"ty\">Student</span> *s);</code></pre></div></div><div class=\"l-note\"><strong>Hangisini kullanmalı?</strong> Klasik <code>#ifndef</code> korumaları %100 taşınabilirdir; <code>#pragma once</code> daha kısadır, biraz daha hızlı olabilir (derleyici dosyayı inode'a göre atlar) ve makro-adı çakışmalarına karşı bağışıktır. Çoğu modern proje <code>#pragma once</code> kullanır; maksimum taşınabilirlik gerektiren kütüphane başlıkları hala geleneksel korumaları kullanır.</div><p class=\"l-text\"><strong><code>#error</code></strong> özel bir mesajla derlemeyi durdurur; <code>#warning</code> durdurmadan tanılama yayar. Yapı zamanı gereksinimlerini zorlamak için kullanın:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> diagnostics.c — #error ve #warning <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#if __STDC_VERSION__ &lt; 201112L</span>\n<span class=\"pp\">#error \"This code requires C11 or later. Use gcc -std=c11.\"</span>\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifdef DEPRECATED_API</span>\n<span class=\"pp\">#warning \"DEPRECATED_API will be removed in v2.0 — migrate to new_api()\"</span>\n<span class=\"pp\">#endif</span>\n\n<span class=\"pp\">#ifndef BUILD_VERSION</span>\n<span class=\"pp\">#error \"BUILD_VERSION must be defined via -DBUILD_VERSION=...\"</span>\n<span class=\"pp\">#endif</span></code></pre></div></div><p class=\"l-text\"><strong>Stringification (<code>#</code>) ve token paste (<code>##</code>)</strong>, makro gövdelerinde kullanılan iki önişlemci operatörüdür. <code>#x</code>, <code>x</code> makro argümanını bir dizgi sabitine dönüştürür. <code>a##b</code>, iki tokeni tek bir tanımlayıcıda birleştirir.</p><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> macro_ops.c — # ve ## operatörleri <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>\n\n<span class=\"cm\">/* Stringification: argümanı bir \"dizgi sabitine\" dönüştür */</span>\n<span class=\"pp\">#define STR(x) #x</span>\n<span class=\"pp\">#define ASSERT_EQ(a, b) </span>\\\n    <span class=\"pp\">((a) == (b) ? printf(STR(a) \" == \" STR(b) \" OK\\n\") </span>\\\n                 <span class=\"pp\">: printf(STR(a) \" != \" STR(b) \" FAIL\\n\"))</span>\n\n<span class=\"cm\">/* Token paste: iki tokeni birleştirip yeni tanımlayıcı oluştur */</span>\n<span class=\"pp\">#define MAKE_VAR(prefix, n) prefix##n</span>\n<span class=\"pp\">#define GETTER(field) </span>\\\n    <span class=\"ty\">int</span> <span class=\"fn\">get_##field</span>(<span class=\"kw\">struct</span> <span class=\"ty\">Point</span> *p) { <span class=\"kw\">return</span> p-&gt;field; }\n\n<span class=\"kw\">struct</span> <span class=\"ty\">Point</span> { <span class=\"ty\">int</span> x, y; };\n<span class=\"fn\">GETTER</span>(x)   <span class=\"cm\">/* genişler: int get_x(struct Point *p) {...} */</span>\n<span class=\"fn\">GETTER</span>(y)   <span class=\"cm\">/* genişler: int get_y(struct Point *p) {...} */</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) {\n    <span class=\"ty\">int</span> <span class=\"fn\">MAKE_VAR</span>(count, <span class=\"num\">1</span>) = <span class=\"num\">42</span>;   <span class=\"cm\">/* int count1 = 42; */</span>\n    <span class=\"ty\">int</span> <span class=\"fn\">MAKE_VAR</span>(count, <span class=\"num\">2</span>) = <span class=\"num\">99</span>;   <span class=\"cm\">/* int count2 = 99; */</span>\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"count1=%d count2=%d\\n\"</span>, count1, count2);\n\n    <span class=\"fn\">ASSERT_EQ</span>(<span class=\"num\">2</span>+<span class=\"num\">2</span>, <span class=\"num\">4</span>);   <span class=\"cm\">/* yazar: 2+2 == 4 OK */</span>\n    <span class=\"fn\">ASSERT_EQ</span>(<span class=\"num\">2</span>+<span class=\"num\">2</span>, <span class=\"num\">5</span>);   <span class=\"cm\">/* yazar: 2+2 != 5 FAIL */</span>\n\n    <span class=\"kw\">struct</span> <span class=\"ty\">Point</span> p = {<span class=\"num\">10</span>, <span class=\"num\">20</span>};\n    <span class=\"fn\">printf</span>(<span class=\"str\">\"x=%d y=%d\\n\"</span>, <span class=\"fn\">get_x</span>(&amp;p), <span class=\"fn\">get_y</span>(&amp;p));\n    <span class=\"kw\">return</span> <span class=\"num\">0</span>;\n}</code></pre></div></div><div class=\"code-wrap\"><div class=\"code-label\"><span>OUTPUT</span></div><div class=\"code-block output-block\"><pre><code>count1=42 count2=99\n2+2 == 4 OK\n2+2 != 5 FAIL\nx=10 y=20</code></pre></div></div><div class=\"l-note\"><strong>Neden önemli:</strong> Stringification, kaynak ifadeyi yazdıran günlükleme makrolarına güç verir (<code>LOG(x)</code> hem <code>\"x\"</code>'i hem değerini gösterir). Token paste ise kod üretimine güç verir — jenerik konteynerler, tipe özgü fonksiyonlar, X-makro tabloları — ayrı bir codegen adımı gerekmeden.</div><div class=\"l-highlight\"><strong><code>#include &quot;...&quot;</code> vs <code>#include &lt;...&gt;</code></strong> — Her iki form da bir dosyayı okuyup içeriğini yerleştirir, ancak farklı dizinleri ararlar.<br><br><strong>Tırnaklar <code>\"header.h\"</code></strong>: önce mevcut kaynak dosyanın dizinini ara, sonra sistem include yoluna düş. <strong>Kendi proje başlıklarınız</strong> için bunu kullanın.<br><br><strong>Açılı parantezler <code>&lt;header.h&gt;</code></strong>: yalnızca sistem include yolunu ara (<code>/usr/include</code>, <code>-I</code> ile verilen yollar, derleyici-kurulu başlıklar). <strong>Standart kütüphane ve üçüncü taraf</strong> başlıkları için bunu kullanın.</div><div class=\"code-wrap\"><div class=\"code-label\"><span>C</span> include_paths.c — pratik örnek <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\">/* Sistem / kütüphane başlıkları — açılı parantez */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;stdio.h&gt;</span>      <span class=\"cm\">/* C standart kütüphane */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;string.h&gt;</span>\n<span class=\"pp\">#include</span> <span class=\"str\">&lt;SDL2/SDL.h&gt;</span>   <span class=\"cm\">/* sistem yolundaki üçüncü taraf */</span>\n\n<span class=\"cm\">/* Kendi proje başlıklarınız — tırnak */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"student.h\"</span>    <span class=\"cm\">/* bu .c dosyasıyla aynı dizinde */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"util/log.h\"</span>   <span class=\"cm\">/* alt dizine göreceli yol */</span>\n<span class=\"pp\">#include</span> <span class=\"str\">\"../shared.h\"</span>  <span class=\"cm\">/* üst dizin */</span>\n\n<span class=\"ty\">int</span> <span class=\"fn\">main</span>(<span class=\"ty\">void</span>) { <span class=\"kw\">return</span> <span class=\"num\">0</span>; }</code></pre></div></div><div class=\"l-warn\"><strong>Yaygın tuzak:</strong> Kendi proje dosyanız için <code>&lt;myheader.h&gt;</code> kullanmak, ancak derleyiciye <code>-I.</code> geçirirseniz çalışır. Kırılgan ve yanıltıcıdır. <strong>Proje için tırnak, kütüphaneler için açılı parantez</strong> — bu sözleşme, niyeti okuyuculara ve araçlara açık hale getirir.</div><p class=\"l-text\">Arama yolu <code>-I</code> derleyici bayrağı ile genişletilebilir:</p><div class=\"code-wrap\"><div class=\"code-label\"><span>BASH</span> Include dizinleri ekleme <button class=\"code-copy\">COPY</button></div><div class=\"code-block\"><pre><code><span class=\"cm\"># ./include'i arama yoluna ekle (hem \"...\" hem &lt;...&gt; için)</span>\ngcc -Iinclude -o app main.c\n\n<span class=\"cm\"># Birden çok yol sırayla aranır</span>\ngcc -Iinclude -I/opt/mylib/include -o app main.c\n\n<span class=\"cm\"># Derleyicinin tam olarak hangi yolları aradığını gör</span>\ngcc -v -E -x c /dev/null   <span class=\"cm\"># #include arama yollarını yazar</span></code></pre></div></div><p class=\"l-text\"><strong>Tebrikler!</strong> Artık C'de sağlam bir temele sahipsiniz. Derleme, tipler, işaretçiler, bellek yönetimi, fonksiyonlar, diziler, dizgiler, yapılar, dosya G/Ç ve önişlemciyi anlıyorsunuz. Bu kavramlar sistem programlamanın yapı taşlarıdır ve ister C++'a, ister Rust'a, ister gömülü sistemlere geçin, size iyi hizmet edecektir.</p>"
};
